// Model parsing and identity comparison are separate. Gold IDs are never prompted.
import{rank,planErrors,normalizePlan,directnessErrors,directnessPrompt}from'./retrieval.mjs';
export function scopePrompt(c,question){return JSON.stringify({question,open_proposal:c.title,evidence_as_of:c.as_of});}
export const queryPrompt=scopePrompt;
export function oneField(x,key,valid){return x&&typeof x==='object'&&!Array.isArray(x)&&Object.keys(x).join(',')===key&&valid(x[key]);}
export function queryErrors(x){return planErrors(x);}
export function contractErrors(c){
 const limits={route_system:1800,mention_system:1800,proposal_match_system:1800,query_system:6000,directness_system:2400};
 return Object.entries(limits).filter(([key,max])=>typeof c?.[key]!=='string'||!c[key].trim()||c[key].length>max||/async\s+function|process\.argv|writeFile\(|parseCompletion\(/.test(c[key])).map(([key])=>'invalid_system_prompt:'+key);
}
export async function matchQuestion(c,k,question,call){
 if(contractErrors(k).length)throw Error('Invalid matching contract');
 const route=await call(scopePrompt(c,question),80,k.route_system,k.route_schema),tasks=['REQUEST_TYPE_INTERPRETATION'];
 if(!oneField(route,'route',v=>['QUESTION','VOTING_ADVICE','LATER_EVENTS'].includes(v)))throw Error('Invalid route');
 let scope=route.route==='VOTING_ADVICE'?'VOTING_ADVICE':route.route==='LATER_EVENTS'?'LATER_EVENTS':'CURRENT_PROPOSAL';
 if(scope==='CURRENT_PROPOSAL'){
  const mention=await call(JSON.stringify({question}),100,k.mention_system,k.mention_schema);tasks.push('PROPOSAL_MENTION_EXTRACTION');
  if(!oneField(mention,'mention',v=>typeof v==='string'&&v.length<=160&&question.includes(v)))throw Error('Invalid proposal mention');
  if(mention.mention){
   const match=await call(JSON.stringify({mention:mention.mention,open_proposal:c.title}),80,k.proposal_match_system,k.proposal_match_schema);tasks.push('PROPOSAL_IDENTITY_COMPARISON');
   if(!oneField(match,'same_proposal',v=>typeof v==='boolean'))throw Error('Invalid proposal identity');
   if(!match.same_proposal)scope='OTHER_PROPOSAL';
  }
 }
 const kind=scope==='VOTING_ADVICE'?'VOTING_ADVICE':scope==='CURRENT_PROPOSAL'?'EVIDENCE':'OUTSIDE_EVIDENCE';
 if(kind!=='EVIDENCE')return{plan:{kind,intent:'NONE',focus:'',limit:0},ids:[],tasks,scope:{scope}};
 const raw=await call(scopePrompt(c,question),350,k.query_system,k.query_schema);tasks.push('QUERY_INTERPRETATION');
 // The legacy query schema includes kind; only its search fields are used.
 // Proposal/time identity was resolved above. Retain voting-advice refusal as
 // an additional safety gate, but do not let a missing topic change identity.
 if(raw?.kind==='VOTING_ADVICE'){
  const refusal=normalizePlan(raw);if(planErrors(refusal).length)throw Error('Invalid query');
  return{plan:refusal,ids:[],tasks,scope:{scope:'VOTING_ADVICE'}};
 }
 const plan={...raw,kind:'EVIDENCE'};
 if(planErrors(plan).length)throw Error('Invalid query');
 const ids=[];
 for(const {id}of rank(c,plan.focus).slice(0,3)){
  if(ids.length>=plan.limit)break;
  const card=c.cards.find(x=>x.id===id),check=await call(directnessPrompt(c,question,card,plan.focus),80,k.directness_system,k.directness_schema);
  if(directnessErrors(check).length)throw Error('Invalid directness check');
  if(!tasks.includes('ORIGINAL_QUESTION_DIRECTNESS_CHECK'))tasks.push('ORIGINAL_QUESTION_DIRECTNESS_CHECK');
  if(check.direct)ids.push(id);
 }
 return{plan,ids,tasks,scope:{scope}};
}

