// Public question -> model scope -> model search query -> deterministic retrieval
// -> model relevance. Only immutable reviewed statements may be published.
import {rank,planErrors,directnessErrors,directnessPrompt} from './retrieval.mjs';
export function scopePrompt(caseData,question){return JSON.stringify({question,open_proposal:caseData.title,evidence_as_of:caseData.as_of});}
export function queryPrompt(caseData,question,target){return JSON.stringify({question,open_proposal:caseData.title,evidence_as_of:caseData.as_of,parsed_question:target});}
export function scopeErrors(x){return !x||typeof x!=='object'||Array.isArray(x)||Object.keys(x).join(',')!=='scope'||!['CURRENT_PROPOSAL','OTHER_PROPOSAL','LATER_EVENTS','VOTING_ADVICE'].includes(x.scope)?['invalid_scope']:[];}
export function queryErrors(x){return !x||typeof x!=='object'||Array.isArray(x)||Object.keys(x).sort().join(',')!=='focus,intent,limit'||planErrors({...x,kind:'EVIDENCE'}).length?['invalid_query']:[];}
export const MONEY_TERMS=Object.freeze({PERSONAL_OUTGOING:'personal charge contribution obligation',BENEFIT_INCOMING:'benefit received supplement',PUBLIC_EXPENDITURE:'aggregate annual cost expenditure',UNSPECIFIED:''});
export function roleErrors(x){return !x||typeof x!=='object'||Array.isArray(x)||Object.keys(x).join(',')!=='role'||!Object.hasOwn(MONEY_TERMS,x.role)?['invalid_money_role']:[];}
export async function statementKey(card){return [...new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(JSON.stringify({kind:card.kind,statement:card.statement}))))].map(x=>x.toString(16).padStart(2,'0')).join('');}
export async function sourceRoleMap(caseData,profiles){
 if(!profiles||profiles.status!=='MODEL_DERIVED_ROUTING_METADATA_NOT_HUMAN_REVIEW'||profiles.model!=='swiss-ai/apertus-v1.5-8b'||!Array.isArray(profiles.profiles)||profiles.profiles.length!==caseData.cards.length)throw Error('Invalid source roles');
 const byHash=new Map();for(const p of profiles.profiles){if(Object.keys(p).sort().join(',')!=='role,statement_sha256'||roleErrors({role:p.role}).length||byHash.has(p.statement_sha256))throw Error('Invalid source roles');byHash.set(p.statement_sha256,p.role);}
 const result=new Map();for(const c of caseData.cards){const key=await statementKey(c);if(!byHash.has(key))throw Error('Source role identity mismatch');result.set(c.id,byHash.get(key));}return result;
}
export async function matchQuestion(caseData,contract,question,call){
 if(contractErrors(contract).length)throw Error('Invalid matching contract');
 const scope=await call(scopePrompt(caseData,question),80,contract.scope_system,contract.scope_schema);
 if(scopeErrors(scope).length)throw Error('Invalid scope');
 const kind=scope.scope==='VOTING_ADVICE'?'VOTING_ADVICE':scope.scope==='CURRENT_PROPOSAL'?'EVIDENCE':'OUTSIDE_EVIDENCE';
 const tasks=['SCOPE_INTERPRETATION'];
 if(kind!=='EVIDENCE')return {plan:{kind,intent:'NONE',focus:'',limit:0},ids:[],tasks,scope};
 let target=await call(JSON.stringify({question}),160,contract.question_role_system,contract.question_role_schema);
 if(targetErrors(target,question).length){
  // One repair for mechanical grounding only, never for a gold-label mismatch.
  target=await call(JSON.stringify({question,invalid_candidate:target,errors:targetErrors(target,question),constraint:'Actor and predicate must be exact contiguous substrings of question, or empty strings. Return the same schema.'}),160,contract.question_role_system,contract.question_role_schema);
 }
 if(targetErrors(target,question).length)throw Error('Invalid money role');tasks.push('MONEY_ROLE_INTERPRETATION');
 const roles=await sourceRoleMap(caseData,contract.source_roles);
 const query=await call(queryPrompt(caseData,question,target),300,contract.query_system,contract.query_schema);
 if(queryErrors(query).length)throw Error('Invalid query');
 const plan={kind,...query},ids=[];tasks.push('QUERY_INTERPRETATION');
 const eligible={...caseData,cards:caseData.cards.filter(c=>target.role==='UNSPECIFIED'||roles.get(c.id)===target.role)};
 // Financial direction is independently parsed from source-only statements.
 // Generic role terms widen vocabulary, never choose a card or invent an answer.
 for(const {id} of rank(eligible,plan.focus+' '+MONEY_TERMS[target.role]).slice(0,3)){
  if(ids.length>=plan.limit)break;
  const card=caseData.cards.find(c=>c.id===id);
  const check=await call(directnessPrompt(caseData,question,card,plan.focus),80,contract.directness_system,contract.directness_schema);
  if(directnessErrors(check).length)throw Error('Invalid directness check');
  if(!tasks.includes('ORIGINAL_QUESTION_DIRECTNESS_CHECK'))tasks.push('ORIGINAL_QUESTION_DIRECTNESS_CHECK');
  if(check.direct)ids.push(id);
 }
 return {plan,ids,tasks,scope,requested_money_role:target.role};
}
export function contractErrors(contract){
 const limits={scope_system:2400,question_role_system:3000,query_system:2400,directness_system:2400,source_role_system:1800};
 return Object.entries(limits).filter(([key,max])=>typeof contract?.[key]!=='string'||!contract[key].trim()||contract[key].length>max||/async\s+function|process\.argv|writeFile\(|parseCompletion\(/.test(contract[key])).map(([key])=>'invalid_system_prompt:'+key);
}

export function targetErrors(target,question){
 if(!target||typeof target!=='object'||Array.isArray(target)||Object.keys(target).sort().join(',')!=='actor,predicate,role'||roleErrors({role:target.role}).length||typeof target.actor!=='string'||typeof target.predicate!=='string'||target.actor.length>120||target.predicate.length>180)return ['invalid_target_shape'];
 return !question.includes(target.actor)||!question.includes(target.predicate)?['ungrounded_question_span']:[];
}

