// Apertus interprets the question independently of source-only measurement tags.
// The application constrains matches by type; factual prose stays immutable.
import{MODEL}from'./qa.mjs';
import{rank,directnessErrors,directnessPrompt}from'./retrieval.mjs';
export const TOPICS=Object.freeze({PERSONAL_CHARGE:{role:'PERSONAL_OUTGOING',terms:'personal charge contribution obligation'},BENEFIT_RECEIVED:{role:'BENEFIT_INCOMING',terms:'benefit received supplement'},PUBLIC_EXPENDITURE:{role:'PUBLIC_EXPENDITURE',terms:'aggregate annual cost expenditure'},ATTRIBUTION:{terms:''},FINANCING_METHOD:{terms:'financing'},OVERVIEW:{terms:''},OTHER:{role:'UNSPECIFIED',terms:''}});
export function scopePrompt(caseData,question){return JSON.stringify({question,open_proposal:caseData.title,evidence_as_of:caseData.as_of});}
export function queryPrompt(caseData,question,target){return JSON.stringify({question,open_proposal:caseData.title,evidence_as_of:caseData.as_of,parsed_question:target});}
export function scopeErrors(x){return !x||typeof x!=='object'||Array.isArray(x)||Object.keys(x).join(',')!=='scope'||!['CURRENT_PROPOSAL','OTHER_PROPOSAL','LATER_EVENTS','VOTING_ADVICE'].includes(x.scope)?['invalid_scope']:[];}
export function topicErrors(x){return !x||typeof x!=='object'||Array.isArray(x)||Object.keys(x).sort().join(',')!=='issue,topic'||typeof x.issue!=='string'||!x.issue.trim()||x.issue.length>220||!Object.hasOwn(TOPICS,x.topic)?['invalid_topic']:[];}
export function queryErrors(x){return !x||typeof x!=='object'||Array.isArray(x)||Object.keys(x).sort().join(',')!=='focus,intent,limit'||!['SPEAKER','CONTENT'].includes(x.intent)||typeof x.focus!=='string'||!x.focus.trim()||x.focus.length>500||!Number.isInteger(x.limit)||x.limit<1||x.limit>3?['invalid_query']:[];}
export async function textKey(text){return [...new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(text)))].map(x=>x.toString(16).padStart(2,'0')).join('');}
export const statementKey=card=>textKey(JSON.stringify({kind:card.kind,statement:card.statement}));
export async function sourceRoleMap(caseData,profiles,system){
 if(!profiles||profiles.status!=='MODEL_DERIVED_ROUTING_METADATA_NOT_HUMAN_REVIEW'||profiles.model!==MODEL||!Array.isArray(profiles.profiles)||profiles.profiles.length!==caseData.cards.length||profiles.source_system_sha256!==await textKey(system))throw Error('Invalid source roles');
 const byHash=new Map();for(const p of profiles.profiles){if(Object.keys(p).sort().join(',')!=='role,statement_sha256'||!['PERSONAL_OUTGOING','BENEFIT_INCOMING','PUBLIC_EXPENDITURE','UNSPECIFIED'].includes(p.role)||byHash.has(p.statement_sha256))throw Error('Invalid source roles');byHash.set(p.statement_sha256,p.role);}
 const result=new Map();for(const c of caseData.cards){const key=await statementKey(c);if(!byHash.has(key))throw Error('Source role identity mismatch');result.set(c.id,byHash.get(key));}return result;
}
export function contractErrors(contract){
 const limits={scope_system:2400,question_topic_system:3000,query_system:3000,directness_system:2400,source_role_system:1800};
 return Object.entries(limits).filter(([key,max])=>typeof contract?.[key]!=='string'||!contract[key].trim()||contract[key].length>max||/async\s+function|process\.argv|writeFile\(|parseCompletion\(/.test(contract[key])).map(([key])=>'invalid_system_prompt:'+key);
}
export async function matchQuestion(caseData,contract,question,call){
 if(contractErrors(contract).length)throw Error('Invalid matching contract');
 const scope=await call(scopePrompt(caseData,question),80,contract.scope_system,contract.scope_schema);
 if(scopeErrors(scope).length)throw Error('Invalid scope');
 const kind=scope.scope==='VOTING_ADVICE'?'VOTING_ADVICE':scope.scope==='CURRENT_PROPOSAL'?'EVIDENCE':'OUTSIDE_EVIDENCE',tasks=['SCOPE_INTERPRETATION'];
 if(kind!=='EVIDENCE')return {plan:{kind,intent:'NONE',focus:'',limit:0},ids:[],tasks,scope};
 const target=await call(JSON.stringify({question}),180,contract.question_topic_system,contract.question_topic_schema);
 if(topicErrors(target).length)throw Error('Invalid question topic');tasks.push('TOPIC_INTERPRETATION');
 const roles=await sourceRoleMap(caseData,contract.source_roles,contract.source_role_system),type=TOPICS[target.topic];
 const eligible={...caseData,cards:caseData.cards.filter(c=>!type.role||roles.get(c.id)===type.role)};
 if(!eligible.cards.length)return{plan:{kind,intent:'CONTENT',focus:target.issue,limit:1},ids:[],tasks,scope,topic:target.topic};
 const query=await call(queryPrompt(caseData,question,target),300,contract.query_system,contract.query_schema);
 if(queryErrors(query).length)throw Error('Invalid query');
 const plan={kind,...query},ids=[];tasks.push('QUERY_INTERPRETATION');
 // Indexed shortlist only. No model-only fallback, no gold IDs in any prompt.
 for(const {id} of rank(eligible,plan.focus+' '+type.terms).slice(0,3)){
  if(ids.length>=plan.limit)break;
  const card=caseData.cards.find(c=>c.id===id),check=await call(directnessPrompt(caseData,question,card,plan.focus),80,contract.directness_system,contract.directness_schema);
  if(directnessErrors(check).length)throw Error('Invalid directness check');
  if(!tasks.includes('ORIGINAL_QUESTION_DIRECTNESS_CHECK'))tasks.push('ORIGINAL_QUESTION_DIRECTNESS_CHECK');
  if(check.direct)ids.push(id);
 }
 return {plan,ids,tasks,scope,topic:target.topic};
}

import test from 'node:test';import assert from 'node:assert/strict';import{readFileSync}from'node:fs';
import{matchQuestion,contractErrors,sourceRoleMap,statementKey,textKey,queryErrors,scopeErrors,queryPrompt}from'../matching.mjs';
const bundle=JSON.parse(readFileSync(new URL('../public-bundle.json',import.meta.url))),contract=bundle.hosted_query;
test('system prompts cannot silently include evaluator program text again',()=>{
 assert.deepEqual(contractErrors(contract),[]);
 assert.ok(contractErrors({...contract,directness_system:contract.directness_system+'\nasync function call(request,traces){writeFile(out,c.ids)}'}).length);
 assert.ok(contractErrors({...contract,directness_system:'x'.repeat(2401)}).length);
});
test('question scope is closed and cannot author facts or select IDs',()=>{
 assert.deepEqual(scopeErrors({scope:'OTHER_PROPOSAL'}),[]);
 for(const x of [{scope:'CURRENT_PROPOSAL',fact_ids:['P01']},{scope:'invented'},null])assert.ok(scopeErrors(x).length);
 for(const x of [{intent:'CONTENT',focus:'budget',limit:1,text:'invented'},{intent:'NONE',focus:'',limit:0}])assert.ok(queryErrors(x).length);
});
test('source role binding survives renamed/reordered IDs, but rejects changed source wording',async()=>{
 const renamed={...bundle.case,cards:bundle.case.cards.map((c,i)=>({...c,id:'anonymous-'+(17+i)})).reverse()},map=await sourceRoleMap(renamed,contract.source_roles,contract.source_role_system);assert.equal(map.size,renamed.cards.length);
 for(const c of renamed.cards){const key=await statementKey(c);assert.equal(map.get(c.id),contract.source_roles.profiles.find(p=>p.statement_sha256===key).role);}
 await assert.rejects(sourceRoleMap({...renamed,cards:renamed.cards.map((c,i)=>i?c:{...c,statement:c.statement+' changed'})},contract.source_roles,contract.source_role_system),/identity mismatch/);
});
test('typed monetary routing rejects a tempting aggregate candidate despite model relevance=true',async()=>{
 const cards=[{id:'new-a',title:'Public spending',kind:'COST_PROJECTION',statement:'The public system would spend 900 tokens.',citations:[]},{id:'new-b',title:'Membership charge',kind:'DIRECT_PROVISION',statement:'Each member would owe 12 tokens.',citations:[]}],caseData={title:'Fictional club reform',as_of:'2020',cards};
 const profiles={model:'swiss-ai/apertus-v1.5-8b',status:'MODEL_DERIVED_ROUTING_METADATA_NOT_HUMAN_REVIEW',source_system_sha256:await textKey(contract.source_role_system),profiles:await Promise.all(cards.map(async(c,i)=>({statement_sha256:await statementKey(c),role:i?'PERSONAL_OUTGOING':'PUBLIC_EXPENDITURE'})))},seen=[];
 const result=await matchQuestion(caseData,{...contract,source_roles:profiles},'Do members owe money?',async(prompt,max,system,schema)=>{seen.push(JSON.parse(prompt));if(schema.properties.scope)return{scope:'CURRENT_PROPOSAL'};if(schema.properties.issue)return{issue:'Member payment obligation',topic:'PERSONAL_CHARGE'};if(schema.properties.focus)return{intent:'CONTENT',focus:'total public spending',limit:1};return{direct:true};});
 assert.deepEqual(result.ids,['new-b']);assert.ok(!seen.filter(p=>p.candidate).some(p=>p.candidate.statement.includes('900')));assert.ok(!JSON.stringify(seen).includes('new-a'));assert.ok(!JSON.stringify(seen).includes('new-b'));
});
test('out-of-proposal scope makes no source matching calls and topic cannot author facts',async()=>{
 let calls=0;const result=await matchQuestion(bundle.case,contract,'Another proposal?',async()=>{calls++;return{scope:'OTHER_PROPOSAL'}});assert.equal(calls,1);assert.deepEqual(result.ids,[]);assert.equal(result.plan.kind,'OUTSIDE_EVIDENCE');
 let n=0;await assert.rejects(matchQuestion(bundle.case,contract,'Do workers pay?',async()=>++n===1?{scope:'CURRENT_PROPOSAL'}:{issue:'benefit',topic:'BENEFIT_RECEIVED',text:'invented'}),/Invalid question topic/);
});
test('query planning receives no source answers or ledger IDs',()=>{
 const data=JSON.parse(queryPrompt(bundle.case,'A public question','UNSPECIFIED'));assert.equal(data.search_index,undefined);assert.ok(!bundle.case.cards.some(c=>JSON.stringify(data).includes(c.statement))); assert.equal(data.reference,undefined);
});

test('a source-classifier prompt change invalidates cached classifications',async()=>{
 await assert.rejects(sourceRoleMap(bundle.case,contract.source_roles,contract.source_role_system+' changed'),/Invalid source roles/);
});
test('non-financial topic cannot publish a financial statement through a permissive relevance judgment',async()=>{
 let n=0;const answer=await matchQuestion(bundle.case,contract,'A non-financial question?',async(prompt,max,system,schema)=>{n++;if(schema.properties.scope)return{scope:'CURRENT_PROPOSAL'};if(schema.properties.issue)return{issue:'An effect outside the indexed financial measurements',topic:'OTHER'};throw Error('No financial search or check should run');});assert.deepEqual(answer.ids,[]);assert.equal(n,2);
});

